def transform(grid):
    from functools import lru_cache

    h, w = len(grid), len(grid[0])
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != 0]
    if not cells:
        return [[0] * w for _ in range(h)]

    candidates = []
    corner_colors = {(0, 0): 2, (0, 1): 4, (1, 0): 3, (1, 1): 5}

    for r in range(h - 1):
        for c in range(w - 1):
            corners = [(r, c), (r, c + 1), (r + 1, c), (r + 1, c + 1)]
            present = [p for p in corners if grid[p[0]][p[1]] != 0]

            if len(present) == 4:
                mask = sum(1 << (rr * w + cc) for rr, cc in present)
                candidates.append((mask, 1, r, c))

            for missing in corners:
                included = [p for p in corners if p != missing]
                if all(grid[rr][cc] != 0 for rr, cc in included):
                    mask = sum(1 << (rr * w + cc) for rr, cc in included)
                    candidates.append((mask, corner_colors[(missing[0] - r, missing[1] - c)], r, c))

    by_cell = [[] for _ in range(h * w)]
    for cand in candidates:
        mask = cand[0]
        for i in range(h * w):
            if mask & (1 << i):
                by_cell[i].append(cand)

    full_mask = sum(1 << (r * w + c) for r, c in cells)
    INF = 10**9

    def choose_cell(rem):
        best_options = None
        best_cell = None
        bits = rem
        while bits:
            bit = bits & -bits
            i = bit.bit_length() - 1
            options = [x for x in by_cell[i] if (x[0] & rem) == x[0]]
            if not options:
                return i, []
            if best_options is None or len(options) < len(best_options):
                best_cell, best_options = i, options
                if len(options) == 1:
                    break
            bits -= bit
        return best_cell, best_options

    @lru_cache(None)
    def min_tiles(rem):
        if rem == 0:
            return 0
        _, options = choose_cell(rem)
        if not options:
            return INF
        best = INF
        for mask, _, _, _ in options:
            best = min(best, 1 + min_tiles(rem ^ mask))
        return best

    output = [[0] * w for _ in range(h)]
    rem = full_mask
    while rem:
        _, options = choose_cell(rem)
        target = min_tiles(rem)
        options.sort(key=lambda x: (-(x[0].bit_count()), x[2], x[3], x[1]))
        chosen = None
        for cand in options:
            if 1 + min_tiles(rem ^ cand[0]) == target:
                chosen = cand
                break
        if chosen is None:
            return [[1 if grid[r][c] else 0 for c in range(w)] for r in range(h)]

        mask, color, _, _ = chosen
        for i in range(h * w):
            if mask & (1 << i):
                output[i // w][i % w] = color
        rem ^= mask

    return output
